-- Rewrites saved phone numbers as ###-###-#### where they hold 10 US digits (or 11 with a leading 1).
-- Anything else is left exactly as it was; it is checked again only when someone changes it.
UPDATE "users" t SET "phone" = n.p FROM (SELECT id, CASE WHEN d ~ '^[0-9]{10}$' THEN substr(d, 1, 3) || '-' || substr(d, 4, 3) || '-' || substr(d, 7, 4) WHEN d ~ '^1[0-9]{10}$' THEN substr(d, 2, 3) || '-' || substr(d, 5, 3) || '-' || substr(d, 8, 4) END AS p FROM (SELECT id, regexp_replace("phone", '[^0-9]', '', 'g') AS d FROM "users" WHERE "phone" IS NOT NULL) s) n WHERE t.id = n.id AND n.p IS NOT NULL AND t."phone" <> n.p;
--> statement-breakpoint
UPDATE "vendors" t SET "phone" = n.p FROM (SELECT id, CASE WHEN d ~ '^[0-9]{10}$' THEN substr(d, 1, 3) || '-' || substr(d, 4, 3) || '-' || substr(d, 7, 4) WHEN d ~ '^1[0-9]{10}$' THEN substr(d, 2, 3) || '-' || substr(d, 5, 3) || '-' || substr(d, 8, 4) END AS p FROM (SELECT id, regexp_replace("phone", '[^0-9]', '', 'g') AS d FROM "vendors" WHERE "phone" IS NOT NULL) s) n WHERE t.id = n.id AND n.p IS NOT NULL AND t."phone" <> n.p;
