UPDATE "jobs" t SET "contact_phone" = n.p FROM (SELECT id, CASE WHEN d ~ '^[0-9]{10}$' THEN substr(d, 1, 3) || '-' || substr(d, 4, 3) || '-' || substr(d, 7, 4) WHEN d ~ '^1[0-9]{10}$' THEN substr(d, 2, 3) || '-' || substr(d, 5, 3) || '-' || substr(d, 8, 4) END AS p FROM (SELECT id, regexp_replace("contact_phone", '[^0-9]', '', 'g') AS d FROM "jobs" WHERE "contact_phone" IS NOT NULL) s) n WHERE t.id = n.id AND n.p IS NOT NULL AND t."contact_phone" <> n.p;
--> statement-breakpoint
UPDATE "settings" t SET "value" = jsonb_set(t."value", '{agency,phone}', to_jsonb(n.p)) FROM (SELECT id, CASE WHEN d ~ '^[0-9]{10}$' THEN substr(d, 1, 3) || '-' || substr(d, 4, 3) || '-' || substr(d, 7, 4) WHEN d ~ '^1[0-9]{10}$' THEN substr(d, 2, 3) || '-' || substr(d, 5, 3) || '-' || substr(d, 8, 4) END AS p FROM (SELECT id, regexp_replace(coalesce("value"->'agency'->>'phone', ''), '[^0-9]', '', 'g') AS d FROM "settings") s) n WHERE t.id = n.id AND n.p IS NOT NULL AND t."value"->'agency'->>'phone' <> n.p;
